package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

type DateRec struct { // 01 DATE-REC, 12 bytes
	DtId   string // PIC X(4) @0 len=4
	DtYyyy int64  // PIC 9(4) @4 len=4
	DtMm   int64  // PIC 9(2) @8 len=2
	DtDd   int64  // PIC 9(2) @10 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsLeapFlag string // PIC X len=1 = "N"
var WsQ int64       // PIC 9(4) len=4 = 0
var WsR4 int64      // PIC 9(3) len=3 = 0
var WsR100 int64    // PIC 9(3) len=3 = 0
var WsR400 int64    // PIC 9(3) len=3 = 0
var WsMaxDay int64  // PIC 99 len=2 = 0
var WsValid int64   // PIC 99 len=2 = 0
var WsBadMonth int64 // PIC 99 len=2 = 0
var WsBadDay int64   // PIC 99 len=2 = 0

var curRec DateRec

var inputLines []string
var inputIdx int
var inputExhausted bool

func pow10(n int) int64 {
	p := int64(1)
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func truncStore(v int64, digits int) int64 {
	m := pow10(digits)
	// keep low-order digits; values here are non-negative
	r := v % m
	if r < 0 {
		r += m
	}
	return r
}

func format9(v int64, width int) string {
	v = truncStore(v, width)
	s := fmt.Sprintf("%d", v)
	if len(s) < width {
		s = strings.Repeat("0", width-len(s)) + s
	}
	if len(s) > width {
		s = s[len(s)-width:]
	}
	return s
}

func parseNum(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	var v int64 = 0
	for _, c := range s {
		if c >= '0' && c <= '9' {
			v = v*10 + int64(c-'0')
		} else {
			// non-digit: treat as 0 digit? just ignore
			// if space inside, treat as 0? ignore is same for leading spaces
		}
	}
	return v
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func isLeap() bool {
	return WsLeapFlag == "Y"
}

func MAINPARA() {
	// OPEN INPUT DATE-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file missing, treat as empty?
		fmt.Fprintln(os.Stderr, err.Error())
		os.Exit(1)
	}
	sc := bufio.NewScanner(f)
	// allow long lines
	const maxCap = 1024 * 1024
	buf := make([]byte, 0, 64*1024)
	sc.Buffer(buf, maxCap)
	inputLines = nil
	for sc.Scan() {
		line := sc.Text()
		inputLines = append(inputLines, line)
	}
	f.Close()
	inputIdx = 0
	inputExhausted = false

	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	// CLOSE DATE-FILE (already closed)

	// DISPLAY "VALID: " WS-VALID " BAD MONTH: " WS-BAD-MONTH " BAD DAY: " WS-BAD-DAY
	out := "VALID: " + format9(WsValid, 2) + " BAD MONTH: " + format9(WsBadMonth, 2) + " BAD DAY: " + format9(WsBadDay, 2)
	fmt.Println(out)
}

func READPARA() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	// pad/truncate to 12
	// operate on bytes; input is ASCII
	if len(line) < 12 {
		line = line + strings.Repeat(" ", 12-len(line))
	} else if len(line) > 12 {
		line = line[:12]
	}
	curRec.DtId = line[0:4]
	curRec.DtYyyy = parseNum(line[4:8])
	curRec.DtMm = parseNum(line[8:10])
	curRec.DtDd = parseNum(line[10:12])
}

func PROCESSPARA() {
	LEAPPARA()
	dtMm := curRec.DtMm
	if dtMm < 1 || dtMm > 12 {
		WsBadMonth = truncStore(WsBadMonth+1, 2)
		fmt.Println(padRight(curRec.DtId, 4) + " BAD MONTH " + format9(curRec.DtMm, 2))
	} else {
		DAYSPARA()
		dtDd := curRec.DtDd
		if dtDd < 1 || dtDd > WsMaxDay {
			WsBadDay = truncStore(WsBadDay+1, 2)
			fmt.Println(padRight(curRec.DtId, 4) + " BAD DAY " + format9(curRec.DtDd, 2) + " MAX " + format9(WsMaxDay, 2))
		} else {
			WsValid = truncStore(WsValid+1, 2)
			fmt.Println(padRight(curRec.DtId, 4) + " VALID " + format9(curRec.DtYyyy, 4) + "-" + format9(curRec.DtMm, 2) + "-" + format9(curRec.DtDd, 2))
		}
	}
	READPARA()
}

func LEAPPARA() {
	yyyy := curRec.DtYyyy
	q4 := yyyy / 4
	r4 := yyyy % 4
	WsQ = truncStore(q4, 4)
	WsR4 = truncStore(r4, 3)
	q100 := yyyy / 100
	r100 := yyyy % 100
	WsQ = truncStore(q100, 4)
	WsR100 = truncStore(r100, 3)
	q400 := yyyy / 400
	r400 := yyyy % 400
	WsQ = truncStore(q400, 4)
	WsR400 = truncStore(r400, 3)
	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DAYSPARA() {
	switch curRec.DtMm {
	case 2:
		if isLeap() {
			WsMaxDay = 29
		} else {
			WsMaxDay = 28
		}
	case 4, 6, 9, 11:
		WsMaxDay = 30
	default:
		WsMaxDay = 31
	}
}

func main() {
	WsEofFlag = "N"
	WsLeapFlag = "N"
	WsQ = 0
	WsR4 = 0
	WsR100 = 0
	WsR400 = 0
	WsMaxDay = 0
	WsValid = 0
	WsBadMonth = 0
	WsBadDay = 0
	MAINPARA()
}
